'use client';

import React, { useState } from 'react';
import ProductGrid from '../components/ProductGrid/ProductGrid';
import OrderModal from '../components/OrderModal/OrderModal';
import styles from './page.module.css';

// Mock data for initial development
const MOCK_PRODUCTS = [
    {
        id: '1',
        name: 'Sankara Karuvadu (Premium)',
        image: 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?q=80&w=400&auto=format&fit=crop',
        originalPrice: 600,
        discountPercentage: 10,
        finalPrice: 540,
    },
    {
        id: '2',
        name: 'Nethili Karuvadu (Medium)',
        image: 'https://images.unsplash.com/photo-1599043513900-ed6fe01d3833?q=80&w=400&auto=format&fit=crop',
        originalPrice: 400,
        discountPercentage: 15,
        finalPrice: 340,
    },
    {
        id: '3',
        name: 'Vanjiram Karuvadu',
        image: 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?q=80&w=400&auto=format&fit=crop',
        originalPrice: 1200,
        discountPercentage: 5,
        finalPrice: 1140,
    },
    {
        id: '4',
        name: 'Paal Karuvadu',
        image: 'https://images.unsplash.com/photo-1599043513900-ed6fe01d3833?q=80&w=400&auto=format&fit=crop',
        originalPrice: 500,
        discountPercentage: 20,
        finalPrice: 400,
    },
];

export default function Home() {
    const [selectedProduct, setSelectedProduct] = useState<any>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);

    const handleOpenOrder = (product: any) => {
        setSelectedProduct(product);
        setIsModalOpen(true);
    };

    const handleCloseOrder = () => {
        setIsModalOpen(false);
        setSelectedProduct(null);
    };

    const handleSubmitOrder = async (formData: any) => {
        console.log('Order submitted:', formData);

        // Create WhatsApp message
        const message = `New Order Received 🐟
Order ID: JK${Math.floor(1000 + Math.random() * 9000)}
Product: ${formData.productName}
Qty: ${formData.quantity} Kg
Customer: ${formData.customerName}
Phone: ${formData.mobileNumber}
Address: ${formData.address}`;

        const encodedMessage = encodeURIComponent(message);
        const whatsappUrl = `https://wa.me/919XXXXXXXXX?text=${encodedMessage}`;

        // Here we would typically save to DB first then redirect
        // window.open(whatsappUrl, '_blank');

        alert('Order Placed Successfully! Redirecting to WhatsApp...');
        window.location.href = whatsappUrl;

        handleCloseOrder();
    };

    return (
        <div className={styles.main}>
            <header className={styles.header}>
                <div className="container">
                    <h1 className={styles.logo}>THOOTHUKUDI <br /> <span>JOHN KARUVATTU KADAI</span></h1>
                </div>
            </header>

            <section className={styles.hero}>
                <div className="container">
                    <div className={styles.heroContent}>
                        <h2>Authentic Sea-Fresh Dry Fish</h2>
                        <p>From the shores of Thoothukudi to your kitchen doorstep.</p>
                        <button className={styles.ctaButton} onClick={() => document.getElementById('products')?.scrollIntoView({ behavior: 'smooth' })}>
                            Shop Now
                        </button>
                    </div>
                </div>
            </section>

            <section id="products" className={styles.products}>
                <div className="container">
                    <h3 className={styles.sectionTitle}>Our Products</h3>
                    <ProductGrid
                        products={MOCK_PRODUCTS.map(p => ({
                            ...p,
                            onOrder: () => handleOpenOrder(p)
                        }))}
                    />
                </div>
            </section>

            <footer className={styles.footer}>
                <div className="container">
                    <p>&copy; 2024 THOOTHUKUDI JOHN KARUVATTU KADAI. All rights reserved.</p>
                    <p>Contact: +91 9XXXXXXXXX | Email: johnkaruvattukadai@gmail.com</p>
                </div>
            </footer>

            <OrderModal
                product={selectedProduct}
                isOpen={isModalOpen}
                onClose={handleCloseOrder}
                onSubmit={handleSubmitOrder}
            />
        </div>
    );
}
